// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"tokenomics":{"slug":"tokenomics","cat":"basics","en":"Tokenomics","contentLocale":"en","term":"Tokenomics","aka":["token economics","token model"],"short":"Tokenomics is the economic design of a cryptocurrency, covering how many tokens exist, who received them, how new tokens are released and what the token is actually used for.","body":[["Good tokenomics analysis starts with supply: maximum supply, ",["circulating supply","circulating-supply"]," and how fast new tokens are issued through rewards or unlocks. Next comes allocation, meaning what share went to the team, investors, community, treasury and airdrops, and when each group can sell."],["Then look at demand. Does the token pay fees, give governance rights, earn ",["staking","staking"]," rewards or get burned when the product is used? A token with heavy future supply and little real use relies on new buyers to absorb the selling."],"Most projects publish tokenomics in a whitepaper or documentation page, often with a vesting chart. Compare that with what you see on-chain and on data sites. Large unlocks, big insider allocations and unlimited minting rights are common warning signs, while clear schedules and genuine usage are healthier signals."],"example":["Suppose a token has 1 billion maximum supply: 20 percent to the team, 18 percent to investors, 40 percent to community rewards, 12 percent to the treasury and 10 percent to an ",["airdrop","airdrop"],". Team and investor tokens unlock monthly over 36 months after a 12-month cliff. That is 380 million tokens, or about 10.6 million released each month once the cliff ends. If only 150 million tokens circulate today, the first monthly unlock alone adds about 7 percent to circulating supply."],"mistakes":["Only reading the total supply and skipping the vesting and unlock schedule.","Assuming a token has value because it has a use, without checking whether that use creates real demand.","Trusting the project's tokenomics chart without checking on-chain wallets and data sites."],"faq":[{"q":"What makes good tokenomics?","a":"Transparent supply, fair allocation, long vesting for insiders and real uses that create demand. There is no single formula, but heavy insider allocations and unclear minting rights are red flags."},{"q":"What is a vesting cliff?","a":"A cliff is a period at the start when no tokens unlock. After it ends, a lump sum or regular monthly unlocks begin."},{"q":"Where can I find a token's tokenomics?","a":"Check the project's whitepaper or documentation, then compare it with data sites and token unlock trackers."}],"title":"What is tokenomics? Meaning and what to check","description":"Learn what tokenomics means, how supply, allocation and vesting work and the red flags to look for in a token.","related":[["circulating-supply","Circulating supply","Circulating supply is the number of coins or tokens that are publicly available and moving in the market right now, excluding locked, reserved or burned tokens."],["token-unlock","Token unlock","A token unlock is a scheduled event when previously locked tokens, usually held by the team, investors or a treasury, become free to transfer and sell, increasing circulating supply."],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) is a project's value if all of its tokens that will ever exist were already in circulation, calculated as the current price multiplied by the maximum or total supply."],["token-burn","Token burn","A token burn is the permanent removal of tokens from circulation by sending them to an address that nobody can access or by destroying them through a smart contract."],["governance-token","Governance token","A governance token is a crypto token that gives holders the right to vote on a protocol's decisions, such as fee changes, upgrades and treasury spending, in proportion to the tokens they hold or delegate."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"order-book":{"slug":"order-book","cat":"trading","en":"Order book","contentLocale":"en","term":"Order book","aka":["depth","market depth","order book depth"],"short":"An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level.","body":[["Bids appear on one side, usually green, with the highest bid at the top. Asks appear on the other, usually red, with the lowest ask nearest the middle. The gap between the best bid and the best ask is the spread. When a ",["market order","market-order"]," arrives, it fills against these resting orders, starting from the best price."],["Depth is the amount available at each level. A deep book has large size close to the current price, so big orders barely move it. A thin book has little size, so a moderate market order can push through several levels and cause ",["slippage","slippage"],". Depth charts show the same data as two curves."],"Order books change constantly as traders add, cancel and fill orders, and many orders come from market makers and bots. Large visible orders, sometimes called walls, can be cancelled at any time, so do not treat them as guaranteed support or resistance. For your own trades, the book helps you decide whether to use a limit or market order."],"example":["Suppose the ask side of a pair shows 2 coins at 10.00, 3 coins at 10.05 and 5 coins at 10.20 ",["USDT","usdt"],". You place a market buy for 8 coins. You fill 2 at 10.00, 3 at 10.05 and 3 at 10.20, paying 20.00 + 30.15 + 30.60 = 80.75 USDT. Your average price is about 10.09, roughly 0.9 percent above the best ask you saw on screen."],"mistakes":["Placing a large market order without checking how much size sits near the best price.","Treating a big visible wall as a guaranteed floor or ceiling.","Reading the last traded price instead of the bid and ask when deciding what you will actually pay."],"faq":[{"q":"How do you read a crypto order book?","a":"Bids show what buyers are willing to pay and asks show what sellers want. The best bid and best ask meet in the middle, and the quantities show how much you can trade at each price."},{"q":"What does a thin order book mean?","a":"It means there are few orders near the current price, so trades can move the price a lot and cause slippage."},{"q":"Do DEXs have order books?","a":"Some do, such as on-chain order book exchanges, but many DEXs use automated market makers with liquidity pools instead."}],"title":"What is an order book in crypto? How to read it","description":"Learn how to read a crypto order book, what bids, asks and depth mean and how the book causes slippage.","related":[["bid-ask-spread","Bid-ask spread","The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["market-order","Market order","A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price."],["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Why isn't the price on screen my fill price?"},"coin":null,"tool":null,"cta":true},"liquidity":{"slug":"liquidity","cat":"trading","en":"Liquidity","contentLocale":"en","term":"Liquidity","aka":["market liquidity","market depth"],"short":"Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much.","body":[["On an exchange, liquidity shows up in the ",["order book","order-book"],". A liquid market has many buy and sell orders close to the current price, so the ",["bid-ask spread","bid-ask-spread"]," is narrow and a large order fills at nearly the price you see. An illiquid market has few orders, wide gaps between price levels and a wide spread."],["Liquidity matters because it sets your real trading cost. In a thin market, a ",["market order","market-order"]," walks through several price levels and fills at a worse average price, which is called ",["slippage","slippage"],". Thin markets also move more sharply on small orders, which can trigger stop-losses and liquidations."],["Liquidity is not fixed. Major pairs like ",["BTC","bitcoin"],"/",["USDT","usdt"]," are usually deep on large exchanges, while small tokens can be thin even on big venues. It also drops at weekends, during holidays and in sudden sell-offs. In DeFi, liquidity comes from liquidity pools rather than an order book, but the idea is the same: more depth means less price impact."]],"example":"Imagine you want to sell 50,000 coins of a small token. The best bid is 1.000 USDT, but only 10,000 coins are wanted there. The next 20,000 coins are bid at 0.990, and the remaining 20,000 at 0.970. Your market sell brings in 10,000 + 19,800 + 19,400 = 49,200 USDT, an average of 0.984, about 1.6% below the price on screen. On a liquid pair, the same order might fill within 0.05% of the displayed price.","mistakes":["Judging liquidity by the last price or the 24-hour volume figure instead of looking at order book depth near the price.","Placing large market orders in thin pairs and being surprised by the fill price.","Assuming a token that is liquid on one exchange is equally liquid on every exchange."],"faq":[{"q":"How can I check the liquidity of a crypto pair?","a":"Look at the bid-ask spread and at how much volume sits within 1% or 2% of the current price in the order book. Many exchanges show this as a depth chart."},{"q":"Why is low liquidity risky?","a":"Low liquidity means larger slippage, wider spreads and sharper price moves. Getting out of a position quickly can cost much more than expected."}],"title":"What is liquidity in crypto? Meaning and why it matters","description":"Understand crypto liquidity, how order book depth affects your fill price, and how to check whether a market is liquid enough.","related":[["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."],["bid-ask-spread","Bid-ask spread","The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment."],["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees."],["market-maker","Market maker","A market maker is a trader or firm that continuously places both buy and sell orders on a market, providing liquidity and earning from the spread between them."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Why isn't the price on screen my fill price?"},"coin":null,"tool":null,"cta":false},"isolated-margin":{"slug":"isolated-margin","cat":"derivatives","en":"Isolated margin","contentLocale":"en","term":"Isolated margin","aka":["isolated mode","isolated margin mode"],"short":"Isolated margin is a margin mode where each position has its own separate collateral, so a liquidation can only take the margin assigned to that position.","body":[["When you open a trade in isolated mode, you choose how much margin to commit. That amount alone backs the position. If the trade goes badly and hits its ",["liquidation price","liquidation-price"],", you lose that margin, but the rest of your futures balance is untouched."],["This makes risk easy to see and cap, which is why many beginners prefer it. The trade-off is that the position cannot draw on your spare balance in a sharp move, so its liquidation price is closer than it would be in ",["cross margin","cross-margin"]," with the same total funds. You can manually add margin to an isolated position to push the liquidation price further away."],["Isolated margin is useful when you hold several unrelated trades and do not want one to endanger the others. Exchanges let you switch modes, but usually only when you have no open position or orders on that ",["contract","smart-contract"],", and some unified accounts handle modes differently."]],"example":["Suppose your futures account holds 5,000 ",["USDT","usdt"],". You open an isolated 10x long on a small token with 400 USDT of margin, a 4,000 USDT position. The token falls roughly 10% and the position is liquidated. You lose roughly the 400 USDT, but 4,600 USDT stays in your account. In cross mode the same position could have kept drawing on the whole 5,000 USDT as the price fell further."],"mistakes":["Thinking isolated margin cannot be liquidated, when it is often liquidated sooner than cross.","Adding margin repeatedly to an isolated position, which removes the cap it was meant to give.","Forgetting to check which mode is active before opening a trade."],"faq":[{"q":"Is isolated or cross margin better?","a":"Isolated caps the loss on each position, which is easier to control. Cross gives positions more room by sharing your balance, but one bad trade can affect everything."},{"q":"Can I add margin to an isolated position?","a":"Yes. Adding margin moves the liquidation price further from the current price, but it also increases what you can lose on that trade."}],"title":"What is isolated margin in crypto futures?","description":"Learn how isolated margin works, how it caps your loss per position and how it compares with cross margin.","related":[["cross-margin","Cross margin","Cross margin is a margin mode where all your open positions share the available balance in your account as collateral, so profits and spare funds can absorb losses before liquidation."],["portfolio-margin","Portfolio margin","Portfolio margin is a margin system that sets your collateral requirement based on the combined risk of all your positions, so hedged positions need less margin than they would separately."],["liquidation-price","Liquidation price","The liquidation price is the mark price at which your leveraged position will be forcibly closed because your margin would fall to the maintenance margin level."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."]],"lesson":{"id":"E21","slug":"isolated-margin","ep":21,"title":"Isolated margin: putting one trade in its own box"},"coin":null,"tool":null,"cta":false},"index-price":{"slug":"index-price","cat":"derivatives","en":"Index price","contentLocale":"en","term":"Index price","aka":["spot index","price index"],"short":"The index price is a reference price for an asset calculated from a weighted average of spot prices on several major exchanges, used to anchor futures pricing.","body":[["An exchange running a perpetual or delivery ",["contract","smart-contract"]," needs a fair reference for the underlying coin. Instead of relying on its own ",["spot market","spot-trading"]," alone, it pulls prices from several large spot venues and combines them, often with weights and rules that exclude outliers or exchanges that stop updating."],["The index price feeds into the ",["mark price","mark-price"],", which drives liquidations and ",["unrealized PnL","unrealized-pnl"],". It is also the benchmark for the ",["funding rate","funding-rate"],": when the perpetual trades above the index, funding tends to be positive. ",["Delivery futures","delivery-futures"]," usually settle at an average of the index price over a set window before expiry."],"Because each exchange chooses its own sources and weights, index prices differ slightly between exchanges. In DeFi, a similar role is played by oracles, which bring external prices on-chain. If an index relies on too few or thin sources, it can be manipulated, which is why exchanges publish their index components."],"example":"Suppose an exchange's ETH index uses three spot sources with equal weight: 3,010, 3,004 and 2,999 USDT. The index price is (3,010 + 3,004 + 2,999) ÷ 3 = 3,004.33 USDT. If the ETH perpetual trades at 3,019, it sits about 0.5% above the index, a premium that pushes funding higher. If one source suddenly printed 2,800, outlier rules would typically reduce its weight or exclude it.","mistakes":["Assuming the index price is a single exchange's spot price.","Expecting the index to be identical on every derivatives exchange.","Ignoring the index when judging whether funding is likely to be high or low."],"faq":[{"q":"What is the difference between index price and mark price?","a":"The index price is an average of spot prices. The mark price starts from the index and adds a smoothed futures premium; it is what liquidations use."},{"q":"Where can I see the index components?","a":"Most exchanges publish the source exchanges and weights for each index on their contract information or index pages."}],"title":"What is index price in crypto futures? Explained","description":"Learn what the index price is, how exchanges build it from spot markets, and how it links to mark price and funding.","related":[["mark-price","Mark price","The mark price is a fair-value price an exchange uses to calculate unrealized profit and loss and to trigger liquidations, instead of the last traded price."],["last-price","Last traded price","The last traded price is the price at which the most recent trade on an order book was executed, and it is the price you usually see on charts and tickers."],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."],["oracle","Blockchain oracle","A blockchain oracle is a service that brings outside data, most often asset prices, onto a blockchain so smart contracts can use it for actions like liquidations, settlements and swaps."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Liquidation: who pressed the forced-close button?"},"coin":null,"tool":"/funding-rates","cta":false},"yield-farming":{"slug":"yield-farming","cat":"defi","en":"Yield farming","contentLocale":"en","term":"Yield farming","aka":["liquidity mining","farming"],"short":"Yield farming is the practice of moving crypto into DeFi protocols, such as liquidity pools or lending markets, to earn trading fees, interest and extra token rewards.","body":[["A farmer might supply ",["liquidity","liquidity"]," to a ",["DEX","dex"]," pool, stake the LP tokens in a reward ",["contract","smart-contract"],", and claim the project's ",["governance token","governance-token"]," on top of fees. Some strategies stack several protocols or reinvest rewards automatically through vaults."],["High advertised returns usually come from token emissions, new tokens printed to attract liquidity. If many farmers sell those rewards, the reward token's price can fall, and the headline ",["APR","apr-vs-apy"]," shrinks with it. Fee income is more durable, but it depends on ",["trading volume","trading-volume"],"."],"Risks add up with each layer: smart contract bugs in every protocol used, impermanent loss, token price drops, depegs, and gas costs that can eat small positions. Check where the yield comes from before chasing the number."],"example":"Imagine you deposit 10,000 USDC worth of liquidity into a pool advertising 40 percent APR, of which 5 percent is fees and 35 percent comes from a reward token. After three months you earn about 125 USDC in fees and reward tokens that were worth 875 USDC at the start. If the reward token falls 60 percent during that time, those rewards are worth about 350 USDC, so your real return is closer to 475 USDC, before gas and impermanent loss.","mistakes":["Judging a farm by its headline APR without checking how much comes from inflationary rewards.","Farming with small amounts on a chain where gas costs eat most of the rewards.","Leaving funds in a farm after rewards end or the team abandons it."],"faq":[{"q":"Is yield farming the same as staking?","a":"No. Staking usually means locking tokens to help secure a proof-of-stake network. Yield farming means seeking returns from DeFi apps, often including liquidity provision."},{"q":"Is yield farming still profitable?","a":"Returns vary widely with market conditions, reward programs and fees. Sustainable yields are usually far lower than promotional rates."}],"title":"What is yield farming? How DeFi rewards work","description":"What yield farming is, where DeFi yields come from, and why headline APRs can shrink once rewards and risks are counted.","related":[["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees."],["apr-vs-apy","APR vs APY","APR is the simple annual rate of return or interest without compounding, while APY includes the effect of reinvesting earnings, so APY is higher than APR whenever returns compound."],["impermanent-loss","Impermanent loss","Impermanent loss is the shortfall a liquidity provider has compared with simply holding the same tokens, caused by the prices of the pooled tokens moving apart after the deposit."],["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"mev":{"slug":"mev","cat":"defi","en":"MEV (maximal extractable value)","contentLocale":"en","term":"MEV (maximal extractable value)","aka":["MEV","maximal extractable value","miner extractable value","sandwich attack"],"short":"MEV, or maximal extractable value, is the profit that block producers and specialised bots can make by choosing, inserting or reordering transactions inside a block, often at the expense of ordinary users.","body":[[["Pending transactions","mempool"]," wait in a public mempool before they are included in a block. Bots, called searchers, watch it and pay to have their own transactions placed before or after yours. Block builders and validators pick the most profitable order."],["Some MEV is neutral or helpful, such as ",["arbitrage","arbitrage"]," that keeps ",["DEX","dex"]," prices in line and liquidations that keep lending protocols solvent. The harmful kind for users is the sandwich attack: a bot buys just before your swap, lets your trade push the price up, then sells right after."],["You can reduce exposure by setting a tight ",["slippage tolerance","slippage"],", splitting large swaps, using DEX aggregators or wallets that offer MEV protection, and sending transactions through private RPC endpoints that do not broadcast to the public mempool."]],"example":["Suppose you swap 10,000 ",["USDC","usdc"]," for a token on a DEX with a 3 percent slippage tolerance. A bot sees the pending trade and buys first, pushing the price up 2 percent. Your swap fills at that worse price, so you receive about 2 percent fewer tokens, roughly 200 USDC worth. The bot then sells into the higher price and keeps the difference minus gas. With a 0.5 percent slippage limit, the attack would not have been worth doing, because the bot could not push the price that far without your swap failing."],"mistakes":["Setting a high slippage tolerance on large swaps of thinly traded tokens.","Assuming MEV only exists on Ethereum; it appears on many chains with public transaction ordering.","Paying for MEV bot software sold on social media, a common scam."],"faq":[{"q":"What is a sandwich attack?","a":"A bot places a buy before your swap and a sell after it, profiting from the price move your trade causes. You get a worse price."},{"q":"Does MEV affect centralized exchange trades?","a":"Not in the same way. Trades on a centralized exchange are matched off-chain, so public mempool MEV does not apply, though deposits and withdrawals still go on-chain."}],"title":"What is MEV in crypto? Sandwich attacks explained","description":"Learn what MEV is, how searchers reorder transactions, and practical ways to protect your DEX swaps from sandwich attacks.","related":[["mempool","Mempool","The mempool is the waiting area where valid but unconfirmed transactions sit on network nodes until a miner or validator includes them in a block."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."],["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company."],["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"nft":{"slug":"nft","cat":"defi","en":"NFT (non-fungible token)","contentLocale":"en","term":"NFT (non-fungible token)","aka":["NFT","non-fungible token","NFTs"],"short":"An NFT, or non-fungible token, is a unique token on a blockchain that records ownership of a specific item, such as a digital artwork, collectible, game item or membership pass.","body":[["Fungible tokens, like ",["USDT","usdt"]," or ",["ETH","ethereum"],", are interchangeable: one unit equals another. Each NFT has its own token ID, so one cannot simply replace another. On Ethereum, NFTs commonly use the ERC-721 or ERC-1155 standards. Solana, ",["Bitcoin","bitcoin"]," through Ordinals, and other chains have their own formats."],"The token usually points to metadata and an image stored elsewhere, on a server, IPFS or Arweave. Owning the NFT proves you hold that token, but it does not automatically give you copyright or commercial rights to the artwork unless the project's licence says so.",["NFT prices depend on demand for a collection, and ",["liquidity","liquidity"]," can be thin. Many collections sell for far less than their mint price later. Common scams include fake mint sites, impersonated collections and signature requests that let attackers list or transfer your NFTs."]],"example":"Imagine a collection of 10,000 NFTs minted at 0.05 ETH each, raising 500 ETH. Six months later, the cheapest listing, called the floor price, is 0.02 ETH. You own one and list it slightly above the floor at 0.025 ETH. After a 2.5 percent marketplace fee and a creator royalty of 5 percent, you would receive about 0.0231 ETH, less than half of the original mint price.","mistakes":["Assuming owning an NFT gives you copyright over the image.","Signing a marketplace or listing signature on an unfamiliar site.","Valuing a collection by its highest recent sale instead of its floor price and volume."],"faq":[{"q":"What does owning an NFT give you?","a":"Proof that your address holds a specific token, plus any rights or access the project grants. Intellectual property rights depend on the project's licence."},{"q":"Can an NFT be copied?","a":"The image can be copied, but the token ID on the blockchain cannot. Copies of the image are not the same token."}],"title":"What is an NFT? Non-fungible tokens explained","description":"Learn what an NFT is, what owning one really means, how floor prices work, and the common NFT scams to avoid.","related":[["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."],["token-approval","Token approval (allowance)","A token approval is a permission you sign in your wallet that lets a smart contract spend a set amount of a specific token from your address, often needed before swapping or depositing in DeFi."],["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds."],["coin-vs-token","Coin vs token","A coin is the native asset of its own blockchain, such as BTC or ETH, while a token is an asset created on top of an existing blockchain using a smart contract, such as USDT on Ethereum."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"vasp":{"slug":"vasp","cat":"regulation","en":"VASP (virtual asset service provider)","contentLocale":"en","term":"VASP (virtual asset service provider)","aka":["VASP","virtual asset service provider","CASP"],"short":"A VASP (virtual asset service provider) is a business that exchanges, transfers, holds or manages crypto for customers and must follow anti-money laundering rules where it operates.","body":[["The term comes from the FATF and covers exchanges, custodial wallets, brokers, some payment services and firms that run token offerings. Many countries require VASPs to register or obtain a licence before serving local customers. In the EU, the ",["MiCA","mica"]," regulation uses the term CASP, crypto-asset service provider, for licensed firms."],["Being a registered or licensed VASP means the firm is subject to rules such as ",["KYC","kyc"],", ",["AML","aml"]," monitoring, the ",["travel rule","travel-rule"]," and, in some places, capital and custody requirements. It does not mean a regulator guarantees your funds. Registration in one country does not allow a firm to serve customers everywhere."],"For users, checking VASP status is a practical safety step. Look up the firm on your national regulator's public register, check the exact legal entity name, and compare it with the entity in the exchange's terms of service. Global exchanges often run separate entities for different regions, each with its own permissions."],"example":"Suppose an exchange advertises that it is licensed. You open its terms of service and find that your account is with an entity registered in Country A. You check the regulator register of your own country, Country B, and find no listing. A second, smaller exchange shows up on Country B's register under the same entity name as its terms. Of the 2 exchanges, only 1 is authorised to serve you locally under Country B's rules.","mistakes":["Trusting a licence logo on a website without checking the regulator's own register.","Assuming a licence in one country covers users in every country.","Believing registration means the regulator insures or guarantees customer funds."],"faq":[{"q":"Is a crypto exchange a VASP?","a":"Yes, centralized exchanges that hold or exchange crypto for customers are VASPs under FATF definitions, and many countries require them to register or be licensed."},{"q":"What is the difference between a VASP and a CASP?","a":"VASP is the FATF's global term. CASP is the term used in the EU's MiCA regulation for licensed crypto-asset service providers."}],"title":"What is a VASP? Virtual asset service provider meaning","description":"What a VASP is, which crypto businesses count as one, how VASP registration and licensing work and how to check an exchange.","related":[["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["mica","MiCA (EU Markets in Crypto-Assets)","MiCA (Markets in Crypto-Assets) is the European Union regulation that sets common rules for crypto-asset issuers, stablecoins and crypto service providers across all EU member states."],["travel-rule","Travel rule","The travel rule is an anti-money laundering requirement that makes crypto service providers share sender and recipient information when they transfer crypto for customers."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Find the real door first: don't open an account on a fake platform"},"coin":null,"tool":"/topics/compliant-exchanges","cta":false},"mica":{"slug":"mica","cat":"regulation","en":"MiCA (EU Markets in Crypto-Assets)","contentLocale":"en","term":"MiCA (EU Markets in Crypto-Assets)","aka":["MiCA","MiCAR","Markets in Crypto-Assets Regulation"],"short":"MiCA (Markets in Crypto-Assets) is the European Union regulation that sets common rules for crypto-asset issuers, stablecoins and crypto service providers across all EU member states.","body":[["MiCA creates one rulebook for the EU instead of 27 national regimes. Its ",["stablecoin","stablecoin"]," rules for e-money tokens and asset-referenced tokens applied from 30 June 2024. Its rules for crypto-asset service providers, called CASPs, applied from 30 December 2024, with national transition periods that can run up to 1 July 2026."],["A ",["CASP","vasp"]," licensed in one EU country can passport its services to the others. Licensed firms must meet requirements on governance, capital, custody and safekeeping of client assets, conflicts of interest and clear disclosures. Token issuers must publish a white paper with prescribed information."],["For users, the visible effects include exchanges restricting or ",["delisting","delisting"]," stablecoins that are not MiCA-compliant for EU customers, more detailed onboarding, and clearer complaint procedures. MiCA does not cover everything: most fully decentralized services and ",["NFTs","nft"]," fall largely outside it, and tax remains national. Check whether the specific entity serving you holds a MiCA licence."]],"example":["Suppose you live in Spain and use an exchange whose EU entity received a MiCA licence in another member state. Through passporting, it can serve you. You hold 3,000 units of a stablecoin that has no authorised issuer under MiCA. The exchange announces that EU users can no longer buy that coin but can still sell or withdraw it for a period. You could ",["convert","instant-convert"]," the 3,000 units into a MiCA-compliant stablecoin, paying perhaps a 0.1% fee, which would be 3 units."],"mistakes":["Assuming every exchange operating in the EU is already MiCA licensed while transition periods run.","Thinking MiCA sets crypto tax rules, which remain the job of each country.","Treating a MiCA licence as a guarantee that you cannot lose money trading."],"faq":[{"q":"When did MiCA come into force?","a":"Stablecoin rules applied from 30 June 2024 and service provider rules from 30 December 2024. Some countries allow transition periods up to 1 July 2026 for existing providers."},{"q":"Why are some stablecoins restricted in the EU?","a":"Under MiCA, stablecoins offered to the public need an authorised issuer. Exchanges therefore limit trading of non-compliant stablecoins for EU customers."}],"title":"What is MiCA? EU crypto regulation explained","description":"What MiCA is, when the EU crypto rules took effect, how CASP licences and passporting work, and why some stablecoins are restricted.","related":[["vasp","VASP (virtual asset service provider)","A VASP (virtual asset service provider) is a business that exchanges, transfers, holds or manages crypto for customers and must follow anti-money laundering rules where it operates."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["usdc","USDC","USDC is a US dollar stablecoin issued by Circle, designed to stay at 1 dollar and backed by cash and short-term US government securities, with monthly reserve attestations."],["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Find the real door first: don't open an account on a fake platform"},"coin":null,"tool":null,"cta":false},"dual-investment":{"slug":"dual-investment","cat":"exchange-features","en":"Dual investment","contentLocale":"en","term":"Dual investment","aka":["dual currency investment","dual asset"],"short":"Dual investment is a structured exchange product where you earn a fixed yield but may be paid back in a different coin depending on whether the price ends above or below a target price on settlement.","body":[["You choose a coin such as ",["BTC","bitcoin"],", a target price and a settlement date. In a buy low product, you deposit ",["stablecoins","stablecoin"],"; if the price at settlement is at or below the target, you receive BTC bought at the target price, otherwise you get your stablecoins back. In a sell high product, you deposit BTC; if the price ends at or above the target, you receive stablecoins, otherwise your BTC. You earn the yield in either case."],"Under the hood, it works much like selling an option. The high yield is your compensation for giving up the upside or accepting the downside. If BTC crashes far below your buy low target, you still receive BTC at the target price, which is then worth less.","Funds are locked until settlement, usually with no early exit. The settlement price is typically an index average at a set time, so it can differ from the last trade you see. Terms, coins and yields vary by exchange."],"example":["Suppose BTC trades at 62,000 ",["USDT","usdt"]," and you deposit 6,000 USDT in a 7-day buy low product with a 60,000 target and 20% annualised yield. Interest for 7 days is 6,000 times 0.20 times 7 divided by 365, about 23 USDT. If BTC settles at 61,000, you receive 6,023 USDT. If it settles at 55,000, you receive 6,023 divided by 60,000, about 0.1004 BTC, worth about 5,522 USDT at that moment."],"mistakes":["Treating the high annualised yield as risk-free interest.","Choosing a buy low target on a coin you do not actually want to own.","Forgetting that a sell high product caps your gain if the price rallies far above the target."],"faq":[{"q":"Can you lose money with dual investment?","a":"Yes, in value terms. You always get the yield, but you may be paid in a coin that is worth less than what you deposited, or miss gains above your target."},{"q":"Is dual investment the same as options trading?","a":"It is built on similar mechanics to selling an option, packaged as a simple product. You do not manage the option yourself."}],"title":"What is dual investment in crypto? How it works","description":"How crypto dual investment works, what buy low and sell high mean, how settlement decides your payout and where the risk lies.","related":[["options","Crypto options","Crypto options are contracts that give the buyer the right, but not the obligation, to buy (call) or sell (put) a cryptocurrency at a set strike price on or before a set expiry date."],["crypto-earn","Crypto Earn (savings products)","Crypto Earn refers to exchange savings products that pay you a yield for depositing crypto, either flexible with withdrawal anytime or locked for a fixed term."],["apr-vs-apy","APR vs APY","APR is the simple annual rate of return or interest without compounding, while APY includes the effect of reinvesting earnings, so APY is higher than APR whenever returns compound."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."]],"lesson":null,"coin":null,"tool":null,"cta":false},"unified-trading-account":{"slug":"unified-trading-account","cat":"exchange-features","en":"Unified trading account (UTA)","contentLocale":"en","term":"Unified trading account (UTA)","aka":["UTA","unified account","unified margin account"],"short":"A unified trading account (UTA) is an exchange account mode that lets you trade spot, margin, futures and sometimes options from one balance, with assets shared as collateral.","body":["In older account setups, you move funds between separate spot and futures wallets. A unified account removes most of those transfers. Your coins sit in one place and count as margin across products, often with each asset valued at a discount called a collateral ratio or haircut. Bybit, OKX and other exchanges offer versions of this, with different names and modes.",["The benefit is capital efficiency. You can hold ",["BTC","bitcoin"]," and use it as margin for a ",["USDT","usdt"]," futures position without selling it. Unrealised profit in one position can support another. Some unified accounts offer ",["portfolio margin","portfolio-margin"],", which calculates margin based on the overall risk of your positions."],["The trade-off is shared risk. A large loss in one position can draw on all your assets, and a falling collateral coin reduces margin at the same time. Some modes can automatically borrow when a balance goes negative, which creates interest. Read your exchange's mode descriptions, and use ",["isolated margin","isolated-margin"]," or a ",["sub-account","sub-account"]," for positions you want kept separate."]],"example":["Suppose you hold 1 BTC worth 60,000 USDT in a unified account with a 95% collateral ratio, giving 57,000 USDT of margin value. You open a ",["USDT perpetual","usdt-margined-futures"]," position needing 10,000 USDT margin. If BTC falls 20% to 48,000 USDT, your collateral value drops to 45,600 USDT. If the position also loses 5,000 USDT, your available margin shrinks further, and both effects combine against the same account."],"mistakes":["Forgetting that a falling collateral coin reduces margin for every open position.","Ignoring automatic borrowing that can charge interest on negative balances.","Mixing long-term holdings and high-leverage trades in one unified balance."],"faq":[{"q":"What is the advantage of a unified trading account?","a":"You can use one balance across spot, margin and derivatives and use coins as collateral without selling them, which reduces transfers and improves capital efficiency."},{"q":"Is a unified account riskier?","a":"It can be, because positions and collateral share the same pool. A loss or price drop in one area affects margin for everything else."}],"title":"What is a unified trading account (UTA)?","description":"What a unified trading account is, how shared collateral and haircuts work, and the risks of combining spot and futures margin.","related":[["cross-margin","Cross margin","Cross margin is a margin mode where all your open positions share the available balance in your account as collateral, so profits and spare funds can absorb losses before liquidation."],["portfolio-margin","Portfolio margin","Portfolio margin is a margin system that sets your collateral requirement based on the combined risk of all your positions, so hedged positions need less margin than they would separately."],["sub-account","Sub-account","A sub-account is a separate account created under your main exchange account, with its own balances and positions, used to separate strategies, bots or team members."],["margin-trading","Margin trading","Margin trading is trading with funds borrowed from an exchange, using your own assets as collateral, so you can open larger positions or short-sell."]],"lesson":null,"coin":null,"tool":null,"cta":true},"withdrawal-fee":{"slug":"withdrawal-fee","cat":"exchange-features","en":"Withdrawal fee","contentLocale":"en","term":"Withdrawal fee","aka":["withdraw fee","network fee"],"short":"A withdrawal fee is the amount an exchange charges when you send crypto from your account to an external address, usually to cover the blockchain network fee.","body":[["When you withdraw, the exchange must broadcast a transaction and pay the network's gas or ",["transaction fee","gas-fee"],". Most exchanges charge a fixed fee per withdrawal, set per coin and per network, and adjust it when network costs change. Some add a margin on top; some withdrawals between users of the same exchange are free."],["The network you choose makes a big difference. The same ",["stablecoin","stablecoin"]," can be withdrawn on several networks, and the fee on a congested ",["layer 1","layer-1"]," chain is often much higher than on a ",["layer 2","layer-2"]," or a low-fee chain. The receiving wallet or exchange must support the same network, or funds can be lost or need a manual recovery."],"There is usually also a minimum withdrawal amount. Because the fee is mostly fixed, small withdrawals lose a larger percentage. Fiat withdrawals to a bank have their own separate fees and limits."],"example":["Suppose you want to withdraw 100 ",["USDT","usdt"],". The exchange charges 4 USDT on an ",["Ethereum","ethereum"],"-based network, 1 USDT on a TRON-based network and 0.2 USDT on a layer 2 network. On Ethereum you lose 4%, receiving 96 USDT. On the layer 2 you receive 99.8 USDT, losing only 0.2%. If the receiving exchange only supports the TRON network, you would pay 1 USDT and receive 99 USDT."],"mistakes":["Choosing a network the receiving wallet does not support.","Making many small withdrawals where the fixed fee eats a large share.","Comparing exchanges on trading fees only and ignoring withdrawal fees."],"faq":[{"q":"Why are crypto withdrawal fees so high?","a":"They often reflect the blockchain network's fee at that time plus the exchange's own pricing. Choosing a cheaper supported network usually lowers the cost."},{"q":"Is the withdrawal fee the same on every network?","a":"No. Each network has its own fee, so the same coin can cost much more to withdraw on one chain than another."}],"title":"What is a crypto withdrawal fee? How to pay less","description":"What crypto withdrawal fees are, why they change by coin and network, and how to choose the right network to avoid overpaying.","related":[["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum."],["blockchain-network","Deposit network (chain selection)","A deposit network is the blockchain you choose to move a coin or token over when you deposit to or withdraw from an exchange, and the sending and receiving sides must use the same one."],["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it."],["layer-2","Layer 2 (L2)","A layer 2 (L2) is a network built on top of a layer 1 blockchain that processes transactions off the main chain and posts the results back to it, giving lower fees while borrowing much of the L1's security."]],"lesson":{"id":"E08","slug":"sell-vs-withdraw","ep":8,"title":"I sold. Why isn't the money in my bank?"},"coin":null,"tool":"/rates","cta":false}});
